package packet;
import core.*;
public final class PcapParser{
 public ParseResult<PcapFile> parse(byte[] data){Diagnostics d=new Diagnostics();if(data==null||data.length<24)return ParseResult.failure("pcap.truncated","pcap global header is missing");long magicBe=Endian.u32be(data,0);long magicLe=Endian.u32le(data,0);boolean le;boolean nano=false;if(magicBe==0xa1b2c3d4L)le=false;else if(magicLe==0xa1b2c3d4L)le=true;else if(magicBe==0xa1b23c4dL){le=false;nano=true;}else if(magicLe==0xa1b23c4dL){le=true;nano=true;}else return ParseResult.failure("pcap.magic","unrecognized pcap magic");int vMaj=u16(data,4,le);int vMin=u16(data,6,le);int snap=(int)u32(data,16,le);int link=(int)u32(data,20,le);if(vMaj!=2)d.medium("pcap.version","unexpected pcap major version "+vMaj);if(snap<=0)d.medium("pcap.snaplen","capture snap length is not positive");PcapFile file=new PcapFile(vMaj,vMin,snap,link,le,d);int off=24;while(off<data.length){if(data.length-off<16){d.medium("pcap.record.truncated","record header truncated",off);break;}long sec=u32(data,off,le);long sub=u32(data,off+4,le);int incl=(int)u32(data,off+8,le);int orig=(int)u32(data,off+12,le);off+=16;if(incl<0||incl>data.length-off){d.high("pcap.record.length","captured length exceeds remaining bytes",off);break;}if(orig<incl)d.low("pcap.record.length","original length is smaller than captured length",off);file.add(new PcapRecord(TimeUtil.fromEpochSeconds(sec,nano?sub/1000:sub),incl,orig,SafeSlice.copy(data,off,incl)));off+=incl;if(file.records().size()>100000){d.high("pcap.record.count","record count limit reached");break;}}return ParseResult.of(file,d);}private static int u16(byte[] b,int o,boolean le){return le?Endian.u16le(b,o):Endian.u16be(b,o);}private static long u32(byte[] b,int o,boolean le){return le?Endian.u32le(b,o):Endian.u32be(b,o);}
}
